 "content": "def transform(grid):
    """Restore cells masked with color 2 from the grid's reflection/transpose symmetry."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            candidates = [(r, w - 1 - c), (h - 1 - r, c), (c, r),
                          (h - 1 - c, w - 1 - r)]
            values = [grid[rr][cc] for rr, cc in candidates
                      if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 2]
            if values:
                out[r][c] = values[0]
    return out
